import re, math, json, psycopg2, duckdb, collections
answers=json.load(open('/workspace/answers.json'))
conn=psycopg2.connect(host='dab-postgres',port=5432,dbname='pancancer_clinical',user='postgres',password='postgres')
cur=conn.cursor(); cur.execute('select "Patient_description", histological_type from clinical_info'); rows=cur.fetchall(); conn.close()
patterns=[re.compile(r'In the (.*?) dataset, patient'),re.compile(r'is a (?:MALE|FEMALE) diagnosed with (.*?)\.'),re.compile(r'a (?:MALE|FEMALE) diagnosed with (.*?)\.'),re.compile(r'belongs to the (.*?) cohort\.'),re.compile(r'is enrolled in the study of (.*?)\.'),re.compile(r'case of (.*?), documented with vital'),re.compile(r'patient diagnosed with (.*?), with vital'),re.compile(r'corresponds to a (?:MALE|FEMALE) patient diagnosed with (.*?), with vital'),re.compile(r'identifies patient .*?, a (?:MALE|FEMALE) subject with (.*?)\. Their current vital status')]
def parse(desc):
    barcode=re.search(r'TCGA-[A-Z0-9]{2}-[A-Z0-9]{4}',desc or '')
    gender=re.search(r'\b(MALE|FEMALE)\b',desc or '')
    vital=re.search(r'(?:vital status(?::| recorded as| is| =)?|Vital status(?: recorded as|:)?|current vital status is|documented with vital status =|with vital status)\s*(Alive|Dead)',desc or '',re.I)
    dx=None
    for p in patterns:
        m=p.search(desc or '')
        if m: dx=m.group(1).strip(); break
    return (barcode.group(0) if barcode else None, gender.group(1) if gender else None, vital.group(1).capitalize() if vital else None, dx)
clinical=[]
for desc,hist in rows:
    b,g,v,dx=parse(desc)
    if b and g and v and dx: clinical.append({'barcode':b,'gender':g,'vital_status':v,'diagnosis':dx,'histological_type':hist})
con=duckdb.connect(); con.execute("SET extension_directory='/workspace/.duckdb_extensions'"); con.execute("SET memory_limit='1GB'"); con.execute("ATTACH '/workspace/query_dataset/pancancer_molecular.db' AS molecular_db (READ_ONLY)")
clin_by={r['barcode']:r for r in clinical}
q1_groups=collections.defaultdict(list)
for pb,nc in con.execute("select ParticipantBarcode, normalized_count from molecular_db.RNASeq_Expression where Symbol='IGF2' and normalized_count is not null and normalized_count>=0").fetchall():
    c=clin_by.get(pb)
    if c and c['diagnosis']=='Brain lower grade glioma' and c['histological_type'] and not re.fullmatch(r'\[.*\]',c['histological_type'].strip()):
        q1_groups[c['histological_type']].append(math.log10(float(nc)+1))
q1='; '.join(f'{h}: {sum(q1_groups[h])/len(q1_groups[h]):.4f}' for h in sorted(q1_groups))
mut_all=set(r[0] for r in con.execute("select distinct ParticipantBarcode from molecular_db.Mutation_Data where Hugo_Symbol='CDH1'").fetchall())
brca_alive=[r for r in clinical if r['diagnosis']=='Breast invasive carcinoma' and r['vital_status']=='Alive' and r['histological_type']]
by=collections.defaultdict(list)
for r in brca_alive: by[r['histological_type']].append(r)
rank=[]
for h,rs in by.items():
    m=sum(r['barcode'] in mut_all for r in rs); rank.append((m/len(rs)*100,h,m,len(rs)))
rank=sorted(rank,key=lambda x:(-x[0],x[1]))[:3]
q2='; '.join(f'{h}: {pct:.4f}%' for pct,h,m,n in rank)
mut_pass=set(r[0] for r in con.execute("select distinct ParticipantBarcode from molecular_db.Mutation_Data where Hugo_Symbol='CDH1' and FILTER='PASS'").fetchall())
female=[r for r in clinical if r['diagnosis']=='Breast invasive carcinoma' and r['gender']=='FEMALE' and r['histological_type'] and not re.fullmatch(r'\[.*\]',r['histological_type'].strip())]
by=collections.defaultdict(list)
for r in female: by[r['histological_type']].append(r)
obs=[]
for h,rs in by.items():
    if len(rs)>10:
        m=sum(r['barcode'] in mut_pass for r in rs); obs.append((h,m,len(rs)-m,len(rs)))
cm=sum(x[1] for x in obs); cn=sum(x[2] for x in obs); grand=cm+cn
chi=sum(((o-(n*col/grand))**2)/(n*col/grand) for h,m,nm,n in obs for o,col in [(m,cm),(nm,cn)])
checks={'q1': q1==answers['q1'], 'q2': q2==answers['q2'], 'q3': f'{chi:.4f}'==answers['q3']}
print('answers_match', checks)
print('counts', {'parsed':len(clinical),'lgg':sum(1 for r in clinical if r['diagnosis']=='Brain lower grade glioma'),'q1_join':sum(len(v) for v in q1_groups.values()),'alive_brca':len([r for r in clinical if r['diagnosis']=='Breast invasive carcinoma' and r['vital_status']=='Alive']),'female_brca':len([r for r in clinical if r['diagnosis']=='Breast invasive carcinoma' and r['gender']=='FEMALE']),'q3_included':grand})
if not all(checks.values()): raise SystemExit(1)
